use system.gpu
use system.gpu.atomic.{Atomic}
use system.collections.array
use system.collections.list
use system.os
use system.fs
use system.result

// The largest bin count the contract allows; the device counters are sized for it.
const MAX_BINS = 256

// Reads the one-line config file: "<count> <seed> <bins>".
fn read_config(path String) List<int>
    let fs = Fs()
    match fs.read_file(path)
        Result.Ok(text): return parse_fields(text)
        Result.Err(_): panic(f"cannot read config file {path}")

fn parse_fields(text String) List<int>
    let fields = List<int>()
    for part in text.trim().split(" ")
        if not part.is_empty()
            match part.to_int()
                Some(v): fields.push(v)
                None: panic(f"not a whole number: {part}")
    if fields.length() != 3
        panic("config must hold exactly three numbers: <count> <seed> <bins>")
    fields

// Generates every value on the GPU and counts it into device-side bins.
// Each thread handles one index, so the counts are updated with atomic adds.
fn count_on_gpu(count int, seed int, bins int) Array<int, MAX_BINS>
    gpu var counts = Array<Atomic<i32>, MAX_BINS>()
    if count > 0
        forall i in 0..count
            let a = ((i % 40000) * 1597 + seed + 51749) % 40000
            let b = (a * a + a * 37 + 11) % 40009
            let c = (b * 613 + 7919) % 40009
            let d = (c + (i / 40000) * 7919) % 40009
            let value = d % 1000
            atomic_add(counts, value * bins / 1000, 1)

    // Atomic counters cannot be copied to the host directly, so a kernel reads
    // each one with an atomic add of zero, which returns the current total.
    gpu var result = Array<int, MAX_BINS>()
    forall b in 0..MAX_BINS
        result[b] = atomic_add(counts, b, 0)

    var host = Array<int, MAX_BINS>()
    host = result
    host

fn main()
    let args = Args()
    if args.length() < 1
        panic("usage: main <config-file>")

    let fields = read_config(args.element_at(0))
    let count = fields.element_at(0)
    let seed = fields.element_at(1)
    let bins = fields.element_at(2)

    let host = count_on_gpu(count, seed, bins)
    for b in 0..bins
        println(f"BIN {b} {host.element_at(b)}")
    println(f"TOTAL {count}")

